import{z as E,x as d,o as t,c as m,q as o,j as n,D as r,d as l,s,S as p,b as e}from"./chunks/framework.C8m1ZpeB.js";const L=JSON.parse('{"title":"链式法则与计算图","description":"","frontmatter":{"title":"链式法则与计算图","date":"2026-09-10T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/chain-rule-graph.md","filePath":"llm/chain-rule-graph.md","lastUpdated":1791063341000}'),A={name:"llm/chain-rule-graph.md"};function h(c,a,B,f,u,b){const i=d("Mermaid");return t(),m("div",null,[a[2]||(a[2]=o('<h1 id="链式法则与计算图" tabindex="-1">链式法则与计算图 <a class="header-anchor" href="#链式法则与计算图" aria-label="Permalink to &quot;链式法则与计算图&quot;">​</a></h1><div class="epigraph"><p>复合函数的导数是局部导数的乘积；把每次张量运算记成图上的结点，乘积就沿边反着走。</p><footer>—— 据 Rumelhart, Hinton &amp; Williams, Learning Representations by Back-propagating Errors, Nature 1986；Goodfellow et al., Deep Learning, 2016 整理</footer></div><p><a href="/llm/overfit-wd-earlystop">过拟合、权重衰减与早停</a>假定我们能得到 \\(\\nabla_\\theta L\\)。本课不重谈 \\(\\lambda\\)。缺口是：损失是一长串张量运算复合出来的，\\(L=f_k\\circ\\cdots\\circ f_1\\)，如何把 \\(\\partial L/\\partial\\theta\\) 写成可执行的局部步骤。方法是计算图：结点是张量，边是算子，正向存下需要的中间量，反向沿拓扑逆序乘局部 Jacobian。下一课才把「一层一行」写成矩阵规则。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>优化课把 \\(g=\\nabla L\\) 当黑盒。前向其实是：输入与参数经过矩阵乘、加法、激活、softmax、取负对数，得到标量。若把整条复合函数当成一个符号公式来手工求导，每改一层就要重推。缺口不是新的优化器，而是一条与层数无关的程序：每个算子只提供「输出对输入的局部导数」，链式法则负责把它们接起来。</p><p>多元时「乘积」是 Jacobian 的乘法。形状必须对得上：若 \\(y=f(x)\\)，\\(x\\in\\mathbb{R}^n\\)，\\(y\\in\\mathbb{R}^m\\)，局部导数是 \\(m\\times n\\) 矩阵。标量损失对 \\(y\\) 的梯度是行向量，右乘这个矩阵得到对 \\(x\\) 的梯度。上一课已经用过一个实例：softmax 接交叉熵的局部结果是 \\(p-y\\)，不必物化 \\(K\\times K\\) 的 Jacobian。</p><p><span class="marginnote">「Jacobian 矩阵」名字唬人，内容只是一张敏感度表：第 \\(i\\) 行第 \\(j\\) 列填「第 \\(i\\) 个输出动一小格，第 \\(j\\) 个输入大约要跟着动多少」。它把「这个算子内部怎么算」压缩成「输入扰动如何放大成输出扰动」，链式法则之后做的，不过是一路上把这些表连乘起来。</span></p><h3 id="计算图不是流程图里的「再算一遍前向」" tabindex="-1">计算图不是流程图里的「再算一遍前向」 <a class="header-anchor" href="#计算图不是流程图里的「再算一遍前向」" aria-label="Permalink to &quot;计算图不是流程图里的「再算一遍前向」&quot;">​</a></h3><p>反向不是把前向公式对 \\(\\theta\\) 重新解释一遍，而是每个结点用自己的局部规则，把上游传来的 \\(\\partial L/\\partial\\mathrm{out}\\) 变成 \\(\\partial L/\\partial\\mathrm{in}\\) 与 \\(\\partial L/\\partial\\theta\\)。需要的中间量（例如激活前的 \\(z\\)）要在正向时保存，否则局部导数没有代入点。把反向理解成「用数值扰动估梯度」，那是检验手段，不是本课的算法；有限差分的代价随参数量线性涨，图上的反向只随算子数涨。</p><p><span class="marginnote">为什么正向要多存中间量？因为反向算局部导数时需要「代入当时的数值」：ReLU 的导数取决于 \\(z\\) 的正负，\\(z\\) 若没存下来，梯度传到这一步就不知道该放行还是挡住。这正是训练时显存被激活值吃掉大半的原因，也是「激活检查点、重算换显存」这类技巧存在的前提。</span></p><p><span class="marginnote">同一张量被两个算子读，反向要把两条入边的梯度相加。残差稍后正是这种结构：加法结点把上游梯度原样分给两条输入。本课先承认「多父结点要累加」，不提前讲完残差动机。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>正向：按算子顺序执行，把每个结点的值记在图上。反向：从 \\(L\\) 出发，\\(\\partial L/\\partial L=1\\)，对每个结点 \\(v\\)，</p> \\[\\frac{\\partial L}{\\partial v}=\\sum_{w\\in\\mathrm{children}(v)}\\frac{\\partial L}{\\partial w}\\frac{\\partial w}{\\partial v}. \\]<p>参数 \\(\\theta\\) 是图里没有子结点依赖数据的叶。实现上，每个算子注册 <code>forward</code> 与 <code>backward</code>；<code>backward</code> 吃上游梯度，吐输入梯度。形状规则与<a href="/llm/tensor-shape-broadcast">张量、形状与广播</a>一致：广播过的轴在反向要做 sum，把展开的梯度收束回原来的 \\(1\\) 维。</p>',15)),(t(),n(p,null,{default:r(()=>[s(i,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E8%BE%93%E5%85%A5%22%5D%20--%3E%20F1%5B%22%E7%AE%97%E5%AD%90%20f1%22%5D%0A%20%20TH%5B%22%E5%8F%82%E6%95%B0%22%5D%20--%3E%20F1%0A%20%20F1%20--%3E%20F2%5B%22%E7%AE%97%E5%AD%90%20f2%22%5D%0A%20%20F2%20--%3E%20L%5B%22%E6%8D%9F%E5%A4%B1%20L%22%5D%0A%20%20L%20--%3E%20B2%5B%22%E5%8F%8D%E5%90%91%20f2%22%5D%0A%20%20B2%20--%3E%20B1%5B%22%E5%8F%8D%E5%90%91%20f1%22%5D%0A%20%20B1%20--%3E%20GTH%5B%22%E5%AF%B9%E5%8F%82%E6%95%B0%E7%9A%84%E6%A2%AF%E5%BA%A6%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"链式法则把全局导数分解成局部矩阵乘。只要每个算子的局部导数正确，整图正确——这是模块化的来源。错误几乎总是：忘了累加多条入边、忘了把广播的梯度求和、在原地修改了正向还需要的缓冲。数值上，许多局部 Jacobian 并不物化：矩阵乘的反向是两次 GEMM，softmax+CE 是一次减法，ReLU 是一次掩码。后课「一行一层」会把常见层的局部规则列成表。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"可以把链式法则想成换汇：人民币先换美元、再换欧元，总汇率就是两段汇率的乘积。损失对参数的「总汇率」同理，等于沿途每个算子各自那一小段汇率的连乘——每个算子只需报出自己的局部汇率，不必知道上游换了多少道手。")],-1)),(t(),n(p,null,{default:r(()=>[s(i,{id:"mermaid-51",class:"mermaid",graph:"flowchart%20LR%0A%20%20X%5B%22%E8%BE%93%E5%85%A5%20x%22%5D%20--%3E%20MM%5B%22%E7%9F%A9%E9%98%B5%E4%B9%98%20z%20%3D%20Wx%22%5D%0A%20%20W%5B%22%E5%8F%82%E6%95%B0%20W%22%5D%20--%3E%20MM%0A%20%20MM%20--%3E%20RL%5B%22ReLU%20a%20%3D%20relu(z)%22%5D%0A%20%20RL%20--%3E%20CE%5B%22softmax%20%2B%20%E4%BA%A4%E5%8F%89%E7%86%B5%20L%22%5D%0A%20%20CE%20--%3E%7C%22%E5%B1%80%E9%83%A8%E5%AF%BC%E6%95%B0%20p%20%E2%88%92%20y%22%7C%20RL%0A%20%20RL%20--%3E%7C%22%E5%B1%80%E9%83%A8%E5%AF%BC%E6%95%B0%EF%BC%9A%E6%AD%A3%E8%B4%9F%E6%8E%A9%E7%A0%81%22%7C%20MM%0A%20%20MM%20--%3E%7C%22%E4%B8%A4%E6%AC%A1%20GEMM%22%7C%20GW%5B%22%E6%A2%AF%E5%BA%A6%E5%AF%B9%20W%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p>图还可以被框架拆成正向模式或反向模式自动微分，那是再下一课。本课的默认是反向：从标量 \\(L\\) 回传到许多参数，正好匹配训练。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写每一层的矩阵公式，不比较正向 / 反向 AD 的复杂度。下一课<a href="/llm/backprop-layerwise">反向传播一行一层</a>把线性层与激活的局部规则写出。后课默认：说到「反传」，指沿计算图逆序应用局部导数；梯度形状与参数形状相同。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>复合函数的导数是局部 Jacobian 沿计算图逆序相乘。</li><li>每个算子只注册局部反向；多父结点的梯度相加。</li><li>广播在反向要求和收束；中间量需在正向保存。</li><li>训练走反向模式：一个标量对许多参数。</li><li>出处：Rumelhart et al., Nature 1986；Goodfellow et al., Deep Learning, 2016。</li></ul>',5))])}const _=E(A,[["render",h]]);export{L as __pageData,_ as default};
